#include <iostream>
#include <cstdint>
#include <limits>
uint8_t sat_add(uint8_t a, uint8_t b) {
    uint16_t sum = static_cast<uint16_t>(a) + b;
    return sum > 255 ? 255 : static_cast<uint8_t>(sum);
}
int main() {
    std::cout << (int)sat_add(200, 100) << " " << (int)sat_add(40, 15) << "\n";
    return 0;
}
